//! Replays the vanilla argument goldens (`fixtures/args/<type>_golden.txt`, generated by `ArgsGolden.java`, see
//! `scripts/args-golden.sh`) against our argument parsers: per input the reader cursor after the parse, the value
//! rendering, every parse exception, the execute error and the suggestions at the end of the input.
#![allow(dead_code)]

#[path = "../command_common/mod.rs"]
mod command_common;

use mc_brigadier::utf16::{java_hash, len16};
use mc_brigadier::{ArgumentBuilder, ArgumentType, CommandDispatcher, ImmutableStringReader, LiteralArgumentBuilder, ParsedValue, RequiredArgumentBuilder};
use mc_game::commands::command_build_context::AccessRegistries;
use mc_game::commands::{CommandBuildContext, CommandSourceStack};
use mc_game::server::permissions::PermissionSet;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::sync::Arc;

pub type Arg = Arc<dyn ArgumentType<CommandSourceStack>>;

/// The source value renderings that need one use (`ArgsSpecs.renderSource`).
pub fn render_source() -> CommandSourceStack {
    use mc_core::phys::{Vec2, Vec3};
    CommandSourceStack::compilation_context(PermissionSet::AllPermissions)
        .with_position(Vec3 { x: 1.5, y: 64.25, z: -2.75 })
        .with_rotation(Vec2 { x: 12.5, y: 40.0 })
}

/// Java `esc` of the generator.
pub fn esc(s: &str) -> String {
    let mut b = String::new();
    for c in s.chars() {
        match c {
            '\\' => b.push_str("\\\\"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => b.push_str(&format!("\\u{:04x}", c as u32)),
            c => b.push(c),
        }
    }
    b
}

pub fn unesc(s: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' {
            if chars[i + 1] == '\\' {
                out.push('\\');
                i += 2;
            } else {
                let hex: String = chars[i + 2..i + 6].iter().collect();
                let unit = u32::from_str_radix(&hex, 16).expect("hex escape");
                out.push(char::from_u32(unit).expect("lone surrogate in fixture"));
                i += 6;
            }
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

fn exception_line(e: &mc_brigadier::CommandSyntaxException) -> String {
    format!("{}@{}", esc(&e.get_message()), e.get_cursor().map_or(-1, |c| c as i64) - 2)
}

fn suggestion_line(s: &mc_brigadier::Suggestions) -> String {
    let mut all = String::new();
    let mut items = Vec::new();
    for x in s.get_list() {
        let item = format!("{}{}", esc(x.get_text()), x.get_tooltip().map_or(String::new(), |t| format!("\u{1}{}", esc(&t.get_string()))));
        all.push_str(&item);
        all.push('\t');
        items.push(item);
    }
    let shown = if items.len() > 40 { &items[..8] } else { &items[..] };
    let r = s.get_range();
    format!("S {}-{} {} {} {}", r.get_start() as i64 - 2, r.get_end() as i64 - 2, items.len(), java_hash(&all), shown.join("\t"))
}

/// `make` builds the argument type under test from the server's command build context; `render` mirrors the
/// generator's value rendering.
pub fn replay(
    name: &str,
    fixture: &str,
    make: impl Fn(&CommandBuildContext) -> Arg,
    render: impl Fn(&ParsedValue, &CommandSourceStack) -> String,
) {
    mc_game::commands::BrigadierExceptions::install();
    mc_game::commands::install_text_validators();
    let (mut server, _keep) = command_common::test_server();
    let build_context = CommandBuildContext::simple(
        Arc::new(AccessRegistries(server.registries.composite_access().clone())),
        mc_world::level_storage::FeatureFlagSet::VANILLA,
    );
    let dispatcher = CommandDispatcher::<CommandSourceStack>::new();
    dispatcher.register(
        LiteralArgumentBuilder::literal("t").then(RequiredArgumentBuilder::argument_shared("a", make(&build_context)).executes(|_| Ok(1))),
    );
    let mut records: Vec<(String, String, Vec<&str>)> = Vec::new();
    for line in fixture.lines() {
        if let Some(rest) = line.strip_prefix("@ ") {
            let (variant, input) = rest.split_once(' ').expect("variant");
            records.push((variant.to_owned(), unesc(input), Vec::new()));
        } else {
            records.last_mut().expect("record").2.push(line);
        }
    }
    assert!(records.len() >= 200, "{name}: corpus too small ({})", records.len());
    let render_source = render_source();
    let mut mismatches = Vec::new();
    for (variant, input, expected) in &records {
        let perms = if variant == "none" { PermissionSet::NoPermissions } else { PermissionSet::AllPermissions };
        let source = CommandSourceStack::compilation_context(perms);
        let command = format!("t {input}");
        let ours = mc_game::commands::server_access::enter_server(&mut server, || {
            catch_unwind(AssertUnwindSafe(|| {
                let mut out = Vec::new();
                let parse = dispatcher.parse(&command, source.clone());
                out.push(format!("R {}", parse.get_reader().get_cursor() as i64 - 2));
                match parse.get_context().get_arguments().get("a") {
                    None => out.push("A -".to_owned()),
                    Some(arg) => out.push(format!(
                        "A {}-{} {}",
                        arg.get_range().get_start() as i64 - 2,
                        arg.get_range().get_end() as i64 - 2,
                        esc(&render(arg.get_result(), &render_source))
                    )),
                }
                for (_, e) in parse.get_exceptions() {
                    out.push(format!("X {}", exception_line(e)));
                }
                out.push(match dispatcher.execute_parsed(&parse) {
                    Ok(_) => "E ok".to_owned(),
                    Err(e) => format!("E {}", exception_line(&e)),
                });
                out.push(suggestion_line(&dispatcher.get_completion_suggestions(&parse)));
                out
            }))
            .unwrap_or_else(|_| vec!["THREW".to_owned()])
        });
        // a runtime exception while parsing is reported as `THREW` by the generator too
        let expected_lines: Vec<String> = expected.iter().map(|s| s.to_string()).collect();
        if ours != expected_lines {
            let diff = ours
                .iter()
                .zip(expected_lines.iter())
                .find(|(a, b)| a != b)
                .map(|(a, b)| format!("ours:     {a}\n  vanilla:  {b}"))
                .unwrap_or_else(|| format!("line count ours {} vanilla {}\n  ours: {ours:?}\n  vanilla: {expected_lines:?}", ours.len(), expected_lines.len()));
            mismatches.push(format!("[{variant}] input {input:?} (len16 {}):\n  {diff}", len16(input)));
        }
    }
    if !mismatches.is_empty() {
        let shown: Vec<_> = mismatches.iter().take(25).cloned().collect();
        panic!("{name}: {} of {} inputs deviate from vanilla:\n{}", mismatches.len(), records.len(), shown.join("\n"));
    }
}
